// One item per pasted line. Blank lines, "# comments" and duplicates are dropped.
const form = $('Bulk MP3 Request').first().json;
const pick = (...keys) => {
  for (const k of keys) if (form[k] !== undefined && form[k] !== null && form[k] !== '') return String(form[k]);
  return '';
};
const text = pick('items', 'Links, songs or podcast titles');
const typeLabel = pick('content_type', 'Content type');
const trimLabel = pick('trim', 'Trim');
const reviewLabel = pick('review', 'Review names & cut points before export?');

const type = /podcast/i.test(typeLabel) ? 'podcast' : /^music/i.test(typeLabel) ? 'music' : 'auto';
const trim = /^off/i.test(trimLabel) ? 'off' : /^silence only/i.test(trimLabel) ? 'silence' : 'smart';
const review = !/^no/i.test(reviewLabel);
const batch = 'b' + $now.toFormat('yyyyLLdd-HHmmss') + '-' + $execution.id;

const seen = new Set();
const out = [];
for (const raw of text.split(/\r?\n/)) {
  const line = raw.trim();
  if (!line || line.startsWith('#')) continue;
  const key = line.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  out.push({ json: { input: line, type, trim, review, batch } });
}
if (!out.length) throw new Error('Nothing to do: paste at least one link, song or podcast title.');
return out;

// /resolve returns 1 entry per video (a playlist returns many). Emit one item per video.
// If nothing resolved, emit a single marker item so the run still reaches the summary page.
const lines = $('Split lines').all();
const out = [];
$input.all().forEach((item, i) => {
  const src = lines[i] ? lines[i].json : {};
  for (const e of item.json.entries || []) {
    out.push({ json: { ...e, trim: src.trim, batch: src.batch } });
  }
});
return out.length ? out : [{ json: { nothing: true } }];

// Gather every analysis into one item: tracks that are ready + everything that failed.
const msg = (e) => (typeof e === 'string' ? e : (e && (e.message || e.description)) || JSON.stringify(e));
const lines = $('Split lines').all().map((i) => i.json);
const failures = [];

$('Resolve (search / playlist)').all().forEach((it, i) => {
  const r = it.json;
  if (r.error || !(r.entries && r.entries.length)) {
    failures.push({ input: r.input || (lines[i] && lines[i].input), error: r.error ? msg(r.error) : 'no results' });
  }
});

const tracks = [];
const seen = new Set();
if ($('Download & analyze').isExecuted) {
  const entries = $('Found anything?').all().map((i) => i.json);
  $('Download & analyze').all().forEach((it, i) => {
    const r = it.json;
    const e = entries[i] || {};
    if (r.ok) {
      if (seen.has(r.id)) return; // same video pasted twice / via a playlist
      seen.add(r.id);
      tracks.push(r);
    } else {
      failures.push({ input: r.input || e.input || e.url, error: msg(r.error || 'analysis failed') });
    }
  });
}

return [{ json: { tracks, failures, review: lines[0].review, batch: lines[0].batch } }];

// One block of fields per track: file name, keep-range, export/skip - pre-filled with the suggestions.
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const fmt = (sec) => { const m = Math.floor(sec / 60); const s = (sec - m * 60).toFixed(1); return m + ':' + (s < 10 ? '0' : '') + s; };
const { tracks } = $json;
const fields = [];
tracks.forEach((t, idx) => {
  const n = idx + 1;
  const reasons = (t.reasons || []).length
    ? '<ul>' + t.reasons.map((r) => '<li>' + esc(r) + '</li>').join('') + '</ul>'
    : '<p><i>No edits suggested - the whole audio is kept.</i></p>';
  fields.push({
    fieldType: 'html',
    html:
      '<hr><h3>' + n + '. ' + esc(t.video_title) + '</h3>' +
      '<p><a href="' + esc(t.url) + '" target="_blank">source</a> · ' + esc(t.type) + ' · original ' + fmt(t.duration) +
      ' → keeps ' + fmt(t.kept_seconds) + ' · name from ' + esc(t.name_source) + '</p>' +
      reasons +
      '<p>Listen: <a href="' + esc(t.preview_start_url) + '" target="_blank">▶ new start</a> · ' +
      '<a href="' + esc(t.preview_end_url) + '" target="_blank">▶ new ending</a></p>',
  });
  fields.push({
    fieldLabel: n + '. File name (Artist - Song Name)',
    fieldName: 'name_' + n,
    fieldType: 'text',
    defaultValue: t.artist + ' - ' + t.title,
    requiredField: true,
  });
  fields.push({
    fieldLabel: n + '. Keep from - to (m:ss.s - m:ss.s)',
    fieldName: 'range_' + n,
    fieldType: 'text',
    defaultValue: t.range,
    requiredField: true,
  });
  fields.push({
    fieldLabel: n + '. Action',
    fieldName: 'action_' + n,
    fieldType: 'dropdown',
    fieldOptions: { values: [{ option: 'Export' }, { option: 'Skip' }] },
    defaultValue: 'Export',
  });
});
return [{ json: { fields } }];

// Merge the (optionally edited) review answers back onto the analysed tracks.
const c = $('Collect analyses').first().json;
const reviewed = $('Review names & cuts').isExecuted ? $('Review names & cuts').first().json : null;
const answer = (keys, fallback) => {
  if (!reviewed) return fallback;
  for (const k of keys) {
    const v = reviewed[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return fallback;
};

const out = [];
c.tracks.forEach((t, idx) => {
  const n = idx + 1;
  const action = answer(['action_' + n, n + '. Action'], 'Export');
  if (/^skip/i.test(action)) return;
  let name = answer(['name_' + n, n + '. File name (Artist - Song Name)'], t.artist + ' - ' + t.title);
  const range = answer(['range_' + n, n + '. Keep from - to (m:ss.s - m:ss.s)'], t.range);
  name = name.replace(/\.mp3$/i, '').trim();
  const sep = name.indexOf(' - ');
  const artist = sep > 0 ? name.slice(0, sep).trim() : t.artist;
  const title = sep > 0 ? name.slice(sep + 3).trim() : name;
  const untouched = range === t.range;
  out.push({
    json: {
      id: t.id,
      artist,
      title,
      range,
      batch: c.batch,
      fade_in: untouched ? t.fade_in : null,
      fade_out: untouched ? t.fade_out : null,
      source: t.url,
    },
  });
});
return out.length ? out : [{ json: { nothing: true } }];

// Build the final results page.
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const msg = (e) => (typeof e === 'string' ? e : (e && (e.message || e.description)) || JSON.stringify(e));
const c = $('Collect analyses').first().json;
const ran = $('Encode MP3').isExecuted;
const requests = ran ? $('Anything to export?').all().map((i) => i.json) : [];
const results = ran ? $('Encode MP3').all().map((i) => i.json) : [];

const done = [];
const failed = c.failures.map((f) => ({ what: f.input, error: f.error }));
results.forEach((r, i) => {
  const req = requests[i] || {};
  if (r.ok) done.push(r);
  else failed.push({ what: req.artist ? req.artist + ' - ' + req.title : req.source, error: msg(r.error || r.detail || 'export failed') });
});
const skipped = c.tracks.length - requests.filter((r) => !r.nothing).length;

let html = '<h2>' + done.length + ' MP3' + (done.length === 1 ? '' : 's') + ' ready</h2>';
if (done.length) {
  const base = done[0].url.split('/files/')[0];
  html += '<p><a href="' + esc(base) + '/batches/' + encodeURIComponent(c.batch) + '.zip"><b>⬇ Download all as .zip</b></a>' +
    ' &nbsp;·&nbsp; also saved to the processor output folder</p>';
  html += '<table style="width:100%;border-collapse:collapse;text-align:left;font-size:14px">' +
    '<tr><th>File</th><th>Kept</th><th>Length</th><th>Avg kbps</th><th>Size</th></tr>';
  for (const d of done) {
    html += '<tr style="border-top:1px solid #ddd"><td><a href="' + esc(d.url) + '">' + esc(d.file) + '</a></td>' +
      '<td>' + esc(d.range) + '</td><td>' + Math.floor(d.seconds / 60) + ':' + String(Math.round(d.seconds % 60)).padStart(2, '0') +
      '</td><td>' + esc(d.avg_kbps) + '</td><td>' + esc(d.size_mb) + ' MB</td></tr>';
  }
  html += '</table>';
}
if (skipped > 0) html += '<p>' + skipped + ' skipped in review.</p>';
if (failed.length) {
  html += '<h3>' + failed.length + ' failed</h3><ul>' +
    failed.map((f) => '<li><b>' + esc(f.what) + '</b>: ' + esc(f.error) + '</li>').join('') + '</ul>';
}
return [{ json: { html, exported: done.length, failed: failed.length, skipped, batch: c.batch } }];
